#[repr(C)]
pub struct CpPixelT {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub a: u8,
}

#[repr(C)]
pub struct CpImageT {
    pub w: i32,
    pub h: i32,
    pub pix: *mut CpPixelT,
}

pub fn flip_horizontal(img: &mut CpImageT) {
    let w = img.w as usize;
    let h = img.h as usize;
    let flips = h / 2;

    for i in 0..flips {
        let a_offset = w * i;
        let b_offset = w * (h - i - 1);

        for j in 0..w {
            let idx_a = a_offset + j;
            let idx_b = b_offset + j;

            let a_pixel = CpPixelT {
                r: unsafe { (*img.pix.add(idx_a)).r },
                g: unsafe { (*img.pix.add(idx_a)).g },
                b: unsafe { (*img.pix.add(idx_a)).b },
                a: unsafe { (*img.pix.add(idx_a)).a },
            };

            let b_pixel = CpPixelT {
                r: unsafe { (*img.pix.add(idx_b)).r },
                g: unsafe { (*img.pix.add(idx_b)).g },
                b: unsafe { (*img.pix.add(idx_b)).b },
                a: unsafe { (*img.pix.add(idx_b)).a },
            };

            unsafe {
                (*img.pix.add(idx_a)).r = b_pixel.r;
                (*img.pix.add(idx_a)).g = b_pixel.g;
                (*img.pix.add(idx_a)).b = b_pixel.b;
                (*img.pix.add(idx_a)).a = b_pixel.a;

                (*img.pix.add(idx_b)).r = a_pixel.r;
                (*img.pix.add(idx_b)).g = a_pixel.g;
                (*img.pix.add(idx_b)).b = a_pixel.b;
                (*img.pix.add(idx_b)).a = a_pixel.a;
            }
        }
    }
}
